INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES (831,110,1,'Implantación de Sistemas Operativos',14,1,15,'','','','','','','','','',0,1,1,1),(832,110,2,'Sistema Operativo Windows',20,1,10,'<p>El objetivo de esta unidad es que el alumnado profundice en el uso del sistema operativo Windows y sus diferentes posibilidades de configuraci&oacute;n y uso. Deber&aacute; de ser capaz de realizar operaciones b&aacute;sicas de administraci&oacute;n como la gesti&oacute;n de usuarios, ficheros y recursos del sistema.</p>','<p>Esta unidad es importante, ya que, les permitir&aacute; conocer en profundidad uno de los sistemas operativos m&aacute;s utilizados del mundo y conocer en detalle todos sus trucos y bunas pr&aacute;cticas a la hora de usarlo y configurarlo.</p>','<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>','<ol>\r\n<li>Versiones de Windows.</li>\r\n<li>El escritorio.</li>\r\n<li>Las ventanas.</li>\r\n<li>Los archivos y carpetas.</li>\r\n<li>Las unidades.</li>\r\n<li>Administraci&oacute;n b&aacute;sica del sistema.</li>\r\n<li>Los permisos.</li>\r\n<li>Compartir en Windows.</li>\r\n<li>Herramientas administrativas.</li>\r\n<li>Hotkeys.</li>\r\n</ol>','<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n del escritorio de Windows y las diferentes opciones de ventanas.</li>\r\n<li>Explicaci&oacute;n de las operaciones de ficheros y c&oacute;mo trabajan en disco cada seg&uacute;n las que se apliquen.</li>\r\n<li>Uso de diferentes unidades dentro del sistema operativo, manejando su sistema de ficheros y c&oacute;mo administrarlas.</li>\r\n<li>Gesti&oacute;n de permisos dentro del sistema de ficheros de Windows.</li>\r\n<li>Uso de las principales herramientas administrativas en la gesti&oacute;n de controladores.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>','','<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>','','',0,1,1,1),(833,110,3,'Sistema Operativo Linux',24,1,10,'<p>El objetivo de esta unidad es que el alumnado aprenda el uso de un sistema operativo Linux y sus diferentes posibilidades de configuraci&oacute;n y uso. Deber&aacute; de ser capaz de realizar operaciones b&aacute;sicas de administraci&oacute;n como la gesti&oacute;n de usuarios, ficheros y recursos del sistema. Tambi&eacute;n se ense&ntilde;ar&aacute;n nociones b&aacute;sicas de scripting, ya que en este sistema son muy usados y m&aacute;s desde un punto de vista de administraci&oacute;n.</p>','<p>Esta unidad es importante, ya que, los sistemas operativos Linux est&aacute;n presentes en el 90% de los servidores del mundo, por este motivo han de conocer las nociones b&aacute;sicas para poder defenderse ante la gesti&oacute;n de este tipo de sistemas en un entorno profesional.</p>','<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>','<ol>\r\n<li>Sistemas operativos Linux.</li>\r\n<li>El entorno de trabajo de Ubuntu.</li>\r\n<li>Las ventanas.</li>\r\n<li>Los archivos y carpetas.</li>\r\n<li>Las unidades.</li>\r\n<li>Administraci&oacute;n b&aacute;sica.</li>\r\n<li>Los permisos.</li>\r\n<li>Compartir en Ubuntu.</li>\r\n</ol>','<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n de los escritorios en Linux y la realizaci&oacute;n de tareas b&aacute;sicas en la distribuci&oacute;n Ubuntu.</li>\r\n<li>Explicaci&oacute;n de las operaciones de ficheros y c&oacute;mo trabajan en disco cada seg&uacute;n las que se apliquen.</li>\r\n<li>Uso de las unidades dentro del sistema operativo y c&oacute;mo gestionarlas.</li>\r\n<li>Gesti&oacute;n de permisos dentro del sistema de ficheros de Linux.</li>\r\n<li>Configuraci&oacute;n de diferentes servicios dentro de Linux mediante interfaz y terminal.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>','','<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>','','',0,1,1,1),(834,110,4,'Sistemas Operativos en Red',18,1,15,'<p>El objetivo de esta unidad es que el alumnado aprenda los diferentes tipos de redes de las que puede hacer uso un ordenador, especialmente en un entorno empresarial o de oficina. Se profundizar&aacute; en las principales topolog&iacute;as de red y los diferentes servicios que se pueden utilizar en estas.</p>','<p>Esta unidad es importante, ya que, hoy en d&iacute;a Internet es el centro neur&aacute;lgico de cualquier actividad industrial, por tanto es necesario que el alumnado adquiera nociones b&aacute;sicas del funcionamiento de las redes en diferentes escenarios.</p>','<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>','<ol>\r\n<li>Red de comunicaci&oacute;n o datos.</li>\r\n<li>Tipos de redes: clasificaci&oacute;n.</li>\r\n<li>Topolog&iacute;as de red.</li>\r\n<li>Configuraciones l&oacute;gicas de red.</li>\r\n<li>Redes inal&aacute;mbricas.</li>\r\n<li>Impresoras en red.</li>\r\n</ol>','<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n de los principales usos de las redes en escenarios reales.</li>\r\n<li>Evaluaci&oacute;n del uso de los diferentes tipos de redes seg&uacute;n el entorno.</li>\r\n<li>Confecci&oacute;n de redes en simuladores reales para realizar pruebas de conexi&oacute;n.</li>\r\n<li>Compartici&oacute;n de recursos en redes locales desde diferentes sistemas operativos.</li>\r\n<li>Confecci&oacute;n de manuales de usuario para la configuraci&oacute;n.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>','','<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>','','',0,1,1,1),(835,110,5,'El procesador de texto',45,2,20,'<p>El objetivo de esta unidad es que el alumnado aprenda nociones b&aacute;sicas de ofim&aacute;tica, concretamente la elaboraci&oacute;n de documentos de texto haciendo uso de los procesadores de texto m&aacute;s habituales. Deber&aacute;n de elaborar estos documentos con unos m&iacute;nimos de presentaci&oacute;n y estilo que doten de profesionalidad a sus trabajos. &nbsp;</p>','<p>Esta unidad es importante, ya que, hoy en d&iacute;a en cualquier trabajo en el que se utilice un ordenador, es necesario la creaci&oacute;n, elaboraci&oacute;n y edici&oacute;n de documentos de texto, por este motivo cualquier persona ha de poseer unos conocimientos m&iacute;nimos de la materia.</p>','<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>','<ol>\r\n<li>El procesador de texto.</li>\r\n<li>La ventana de Word 2016.</li>\r\n<li>Operaciones sobre documentos.</li>\r\n<li>Partes del documento.</li>\r\n<li>Visualizar el documento.</li>\r\n<li>Acciones b&aacute;sicas sobre el contenido.</li>\r\n<li>Formato de la p&aacute;gina.</li>\r\n<li>Formato de la fuente</li>\r\n<li>Formato del p&aacute;rrafo.</li>\r\n<li>Tablas.</li>\r\n<li>Ilustraciones.</li>\r\n<li>Objetos de texto.</li>\r\n<li>Revisi&oacute;n del texto.</li>\r\n</ol>','<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n de las diferentes funcionalidades de un software de ofim&aacute;tica.</li>\r\n<li>Explicaci&oacute;n de los controles de la interfaz de un editor de texto y sus diferentes opciones.</li>\r\n<li>Confecci&oacute;n de documentos profesionales siguiendo gu&iacute;as de estilos con diferentes tem&aacute;ticas.</li>\r\n<li>Creaci&oacute;n de tablas funcionales dentro de documentos para representar informaci&oacute;n relevante para los estudiantes.</li>\r\n<li>Confecci&oacute;n de gr&aacute;ficos avanzados dentro de documentos.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>','','<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>','','',0,1,1,1),(836,110,6,'Aplicaciones Ofimáticas',17,2,15,'<p>El objetivo de esta unidad es que el alumnado aprenda nociones b&aacute;sicas de ofim&aacute;tica, concretamente la elaboraci&oacute;n de hojas de c&aacute;lculo, presentaciones y uso b&aacute;sico de gestores de bases de datos locales. Deber&aacute;n de elaborar diferentes actividades haciendo uso de estar herramientas simulando operaciones en entornos reales.</p>','<p>Esta unidad es importante, ya que, hoy en d&iacute;a en cualquier trabajo en el que se utilice un ordenador se hace uso de hojas de c&aacute;lculo para presupuesto, presentaciones para proyectos o bases de datos para la gesti&oacute;n de usuario o inventario. Por este motivo, los estudiantes han de alcanzar un nivel b&aacute;sico en estas herramientas para desenvolverse de forma adecuada en el sector.</p>','<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>','<ol>\r\n<li>Suites ofim&aacute;ticas.</li>\r\n<li>Hojas de c&aacute;lculo.</li>\r\n<li>Bases de datos.</li>\r\n<li>Presentaciones multimedia.</li>\r\n<li>Aplicaciones ofim&aacute;ticas en la nube.</li>\r\n</ol>','<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n de las diferentes funcionalidades de un software de hojas de c&aacute;lculo.</li>\r\n<li>Elaboraci&oacute;n de un gestor de notas autom&aacute;tico.</li>\r\n<li>Explicaci&oacute;n de las diferentes funcionalidades de un software de base de datos.</li>\r\n<li>Elaboraci&oacute;n de un gestor de usuarios de gimnasio.</li>\r\n<li>Explicaci&oacute;n de las diferentes funcionalidades de un software de presentaci&oacute;n.</li>\r\n<li>Elaboraci&oacute;n de una presentaci&oacute;n sobre los contenidos estudiados.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>','','<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>','','',0,1,1,1),(837,110,7,'Servicios Básicos de Internet',30,2,7,'<p>El objetivo de esta unidad es que el alumnado aprenda nociones b&aacute;sicas de los servicios m&aacute;s usados en internet, como la configuraci&oacute;n de navegadores, los diferentes buscadores y la comunicaci&oacute;n mediante correos electr&oacute;nicos o plataformas de mensajer&iacute;a instant&aacute;nea.</p>','<p>Esta unidad es importante, ya que, hoy en d&iacute;a en cualquier trabajo se hace uso del correo electr&oacute;nico o de aplicaciones de comunicaci&oacute;n instant&aacute;nea y el alumnado ha de estar familiarizado con estas herramientas. Adem&aacute;s, hacer un buen uso de internet es esencial para ser mas productivo en las tareas de oficina.</p>','<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>','<ol>\r\n<li>Conceptos b&aacute;sicos.</li>\r\n<li>La web.</li>\r\n<li>El navegador.</li>\r\n<li>Los buscadores.</li>\r\n<li>El correo electr&oacute;nico.</li>\r\n<li>La mensajer&iacute;a instant&aacute;nea.</li>\r\n</ol>','<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n y configuraci&oacute;n de un navegador de internet y patrones de b&uacute;squeda en los principales exploradores.</li>\r\n<li>Configuraci&oacute;n de un correo electr&oacute;nico y sus principales caracter&iacute;sticas.</li>\r\n<li>Explicaci&oacute;n del funcionamiento de la mensajer&iacute;a instant&aacute;nea y su presencia en la actualidad</li>\r\n<li>Uso de una plataforma de comunicaci&oacute;n online para crear reuniones virtuales.</li>\r\n<li>Elaboraci&oacute;n de correos electr&oacute;nicos profesionales.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>','','<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>','','',0,1,1,1),(838,110,8,'Servicios Web',10,3,4,'<p>El objetivo de esta unidad es que el alumnado conozca los diferentes servicios web que existen en la actualidad y comprendan su funcionamiento. &nbsp;</p>','<p>Esta unidad es importante, ya que, hoy en d&iacute;a se hace uso de m&uacute;ltiples servicios web, pero en muchas ocasiones no se conoce su funcionamiento interno. Por este motivo, es esencial que el alumnado conozca en qu&eacute; consisten estos servicios en profundidad y aprendan a explotarlos de una forma &oacute;ptima.</p>','<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>','<ol>\r\n<li>Generaciones web.</li>\r\n<li>Foros.</li>\r\n<li>Blogs.</li>\r\n<li>Wikis.</li>\r\n<li>Sindicaci&oacute;n de contenidos.</li>\r\n<li>Redes sociales.</li>\r\n<li>Computaci&oacute;n en la nube.</li>\r\n<li>Gestores de contenidos.</li>\r\n<li>Redes y servicios p2p.</li>\r\n</ol>','<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n sobre qu&eacute; es la web y los principales protocolos que permiten su funcionamiento.</li>\r\n<li>Explicaci&oacute;n de los foros y uso real de uno de ellos.</li>\r\n<li>Creaci&oacute;n de un blog y participaci&oacute;n en una Wiki publica para aportar informaci&oacute;n.</li>\r\n<li>Investigaci&oacute;n sobre el estado del arte de las diferentes redes sociales y explicaci&oacute;n de los diferentes modelos que existen</li>\r\n<li>Manejo de gestores de contenido CMS</li>\r\n<li>Explicaci&oacute;n de las redes P2P y su uso en la actualidad</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>','','<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>','','',0,1,1,1),(839,110,9,'Seguridad Informática',10,3,2,'<p>El objetivo de esta unidad es que el alumnado conozca las principales vulnerabilidades de seguridad de los sistemas y aprenda a protegerse de ellas. En la unidad se explicar&aacute;n buenas pr&aacute;cticas b&aacute;sicas de seguridad para proteger su actividad digital.</p>','<p>Esta unidad es importante, ya que, hoy en d&iacute;a los ciberataques no cesan y cada vez m&aacute;s van en aumento. Por este motivo, esta unidad pretende que el alumnado adquiera consciencia de los peligros de internet, aprenda a identificarlos y protegerse de ellos, garantizando as&iacute; su seguridad en sus futuras actividades digitales.</p>','<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>','<ol>\r\n<li>Seguridad de un sistema inform&aacute;tico.</li>\r\n<li>Tipos de amenazas.</li>\r\n<li>Niveles de seguridad.</li>\r\n<li>An&aacute;lisis y control del riesgo.</li>\r\n<li>Mecanismos de seguridad f&iacute;sica.</li>\r\n<li>Mecanismos de seguridad l&oacute;gica.</li>\r\n<li>Ataques m&aacute;s comunes.</li>\r\n<li>Buenas pr&aacute;cticas.</li>\r\n</ol>','<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n sobre los diferentes ataques inform&aacute;ticos y c&oacute;mo prevenirlos.</li>\r\n<li>Niveles de protecci&oacute;n tanto f&iacute;sica como digital de los componentes inform&aacute;ticos.</li>\r\n<li>Buenas pr&aacute;cticas de ciberseguridad.</li>\r\n<li>Configuraci&oacute;n de un detector de malware.</li>\r\n<li>Configuraci&oacute;n de un bloqueador de rastreadores y scripts en un navegador.</li>\r\n<li>Explicaci&oacute;n y uso de un gestor de contrase&ntilde;as.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>','','<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>','','',0,1,1,1),(840,110,10,'Multimedia',12,3,2,'<p>El objetivo de esta unidad es que el alumnado conozca los diferentes tipos de contenidos multimedia que existen en la actualidad, trabajar con ellos, reconocer plataformas de consumo y realizar conversiones de formatos &uacute;tiles en el d&iacute;a a d&iacute;a.</p>','<p>Esta unidad es importante, ya que, en la actualidad existen numerosos formatos digitales para elaborar multimedia y desde un punto de vista de usuario, es necesario reconocer los principales formatos para trabajar de forma adecuada con cada uno de ellos. Adem&aacute;s, conocer m&eacute;todos de conversi&oacute;n eficaces es de gran ayuda en el trabajo inform&aacute;tico diario.</p>','<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>','<ol>\r\n<li>Contenido multimedia.</li>\r\n<li>Herramientas para la creaci&oacute;n de contenido multimedia.</li>\r\n<li>Plataformas de contenido multimedia.</li>\r\n<li>Herramientas de conversi&oacute;n de formatos.</li>\r\n</ol>','<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n sobre los diferentes formatos multimedia que sirven para producir videos, m&uacute;sica e im&aacute;genes.</li>\r\n<li>Exposici&oacute;n de herramientas de creaci&oacute;n de contenido multimedia.</li>\r\n<li>Investigaci&oacute;n sobre las diferentes plataformas de generaci&oacute;n y consumo de contenido.</li>\r\n<li>Uso de herramientas de conversi&oacute;n de formatos &uacute;tiles para la gesti&oacute;n de documentos y ficheros multimedia.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>','','<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>','','',0,1,1,1);
